"""地球1：身近な大地／地震の発生とゆれの伝わり方／ゆれの大きさと日本列島の地震
（ワーク p22〜29・44、教科書 p68〜83。教科書 p64〜67 の写真は無いので、プレート・隆起などの用語はワークのまとめ p44 を根拠にする）"""
from kbank import T, C, SEQ, N, S, R
from sci import unit

def tm(h, m, s):
    """時刻の答え（7時10分5秒／7時10分05秒／7:10:05 のどれでも正解）"""
    return T(f'{h}時{m}分{s}秒', f'{h}時{m:02d}分{s:02d}秒', f'{h}時{m}分{s:02d}秒', f'{h}:{m:02d}:{s:02d}', f'{h}時{m:02d}分{s}秒')
def hms(t):
    h, r = divmod(t, 3600); m, s = divmod(r, 60); return h, m, s
def tstr(t):
    h, m, s = hms(t); return f'{h}時{m}分{s}秒'

