# 地震の計算に使う数値の組（P波5〜7 km/s、S波3〜4 km/s：教科書p77図16の範囲。時刻はすべて整数秒になるように選んだ）
QUAKES = [
    {'p': 6, 's': 4, 't0': 9 * 3600 + 20 * 60 + 10, 'st': [('A', 60), ('B', 120), ('C', 180)]},
    {'p': 7, 's': 3.5, 't0': 14 * 3600 + 5 * 60 + 40, 'st': [('A', 35), ('B', 105), ('C', 140)]},
    {'p': 5, 's': 3, 't0': 6 * 3600 + 12 * 60 + 50, 'st': [('A', 45), ('B', 90), ('C', 150)]},
    {'p': 6, 's': 3, 't0': 21 * 3600 + 47 * 60 + 30, 'st': [('A', 36), ('B', 72), ('C', 108)]},
]
def fmt(x):
    return str(int(x)) if float(x).is_integer() else str(x)

